没有方差修饰符时，IEnumerable<Dog> 和 IEnumerable<Animal> 是两个完全不相关的类型——即使 Dog 继承 Animal，泛型类型之间也没有继承关系。这会导致很多直觉上应该可以的赋值不合法，迫使开发者做不必要的 `.Cast<T>().ToList()` 或写适配器方法。

方差在接口和委托声明时指定（class 不支持方差，因为 class 通常同时有读写方法），它告诉编译器：这个泛型类型的使用方式保证了赋值是安全的。

**经典的工程场景**：
```csharp
// 事件处理——协变让子类型事件处理器可以直接赋值给父类型回调
EventHandler<MouseEventArgs> handler = (s, e) => { };
EventHandler<object> generalHandler = handler; // 不能这样！EventArgs 是逆变的...

// 实际上 EventHandler<TEventArgs> 没有方差（因为委托体内 T 出现在参数位置）
// 但 Action<T> 是逆变的：
Action<object> log = o => Console.WriteLine(o);
Action<string> stringLog = log; // 合法，逆变
stringLog("hello"); // 实际执行的是 log("hello")

// 读取接口 + 协变 = 灵活的类型安全数据源
IEnumerable<Dog> dogs = GetDogs();
PrintAnimals(dogs); // 合法，IEnumerable 是协变的
void PrintAnimals(IEnumerable<Animal> animals) { foreach (var a in animals) a.Speak(); }
```

**设计建议**：设计只读接口时加 out（如 IReadOnlyRepository<out T>），设计只写接口或消费型接口时加 in（如 IHandler<in T>、IProcessor<in T>）。如果接口既有读又有写，保持不变——安全比灵活重要。

using System;
using System.Collections.Generic;

namespace GenericsVarianceDemo
{
    // -- 类型体系 --
    public class Animal
    {
        public string Name { get; set; }
        public virtual void Speak() => Console.WriteLine("...");
    }

    public class Dog : Animal
    {
        public override void Speak() => Console.WriteLine("Woof!");
    }

    public class Cat : Animal
    {
        public override void Speak() => Console.WriteLine("Meow!");
    }

    // -- 接口定义（协变/逆变/不变） --
    public interface IReadRepository<out T>  // 协变：只读
    {
        T GetById(int id);
        IEnumerable<T> GetAll();
    }

    public interface IProcessor<in T>  // 逆变：只消费
    {
        void Process(T item);
    }

    public interface IRepository<T>  // 不变：既读又写
    {
        T GetById(int id);
        void Add(T item);
    }

    // -- 实现 --
    public class AnimalReadRepository : IReadRepository<Animal>
    {
        private readonly List<Animal> _store = new List<Animal> { new Dog { Name = "Buddy" } };
        public Animal GetById(int id) => _store[id];
        public IEnumerable<Animal> GetAll() => _store;
    }

    public class AnimalProcessor : IProcessor<Animal>
    {
        public void Process(Animal item) => item.Speak();
    }

    // -- 泛型约束示例 --
    public interface IEntity { int Id { get; set; } }

    public class EntityRepository<T> where T : class, IEntity, new()
    {
        private readonly Dictionary<int, T> _store = new Dictionary<int, T>();
        public void Add(T entity) => _store[entity.Id] = entity;
        public T GetById(int id) => _store.TryGetValue(id, out var e) ? e : null;
        public T CreateNew() => new T();  // new() 约束允许此操作
    }

    // -- 泛型缓存（每个封闭类型独立的静态字段） --
    public static class TypeCache<T>
    {
        public static readonly string FullName;
        public static readonly bool IsValueType;
        public static readonly int HashCode;

        static TypeCache()
        {
            var t = typeof(T);
            FullName = t.FullName ?? t.Name;
            IsValueType = t.IsValueType;
            HashCode = t.GetHashCode();
        }
    }

    // -- 泛型方法示例 --
    public static class MathHelper
    {
        public static T Max<T>(T a, T b) where T : IComparable<T>
            => a.CompareTo(b) > 0 ? a : b;
    }

    class Program
    {
        static void Main()
        {
            // 1. 协变：IReadRepository<Dog> 赋值给 IReadRepository<Animal>
            IReadRepository<Dog> dogRepo = new DogReadRepository();
            IReadRepository<Animal> animalRepo = dogRepo;  // 合法，协变
            animalRepo.GetById(0).Speak();  // 输出 "Woof!"

            // 2. 逆变：IProcessor<Animal> 赋值给 IProcessor<Dog>
            IProcessor<Animal> animalProc = new AnimalProcessor();
            IProcessor<Dog> dogProc = animalProc;  // 合法，逆变
            dogProc.Process(new Dog { Name = "Rex" });  // 输出 "Woof!"

            // 3. 不变：List<Dog> 不能赋值给 List<Animal>
            List<Dog> dogs = new List<Dog>();
            // List<Animal> animals = dogs;  // 编译错误！
            // 但 IEnumerable<Dog> 可以：
            IEnumerable<Animal> animals = dogs;  // 合法，IEnumerable 是协变的

            // 4. 泛型约束
            // var badRepo = new EntityRepository<Animal>();  // 编译错误！Animal 不满足 IEntity
            // EntityRepository<Dog> 也需要 Dog 实现 IEntity

            // 5. 泛型缓存——每种类型的静态字段独立
            Console.WriteLine(TypeCache<int>.FullName);      // System.Int32
            Console.WriteLine(TypeCache<string>.FullName);   // System.String
            Console.WriteLine(TypeCache<int>.IsValueType);   // True
            Console.WriteLine(TypeCache<string>.IsValueType); // False

            // 6. Func 的同时协变逆变
            Func<Animal, Dog> animalToDog = a => new Dog { Name = a.Name };
            Func<Dog, Animal> dogToAnimal = animalToDog;  // T 逆变, TResult 协变
        }
    }

    // 协变接口的实现类
    public class DogReadRepository : IReadRepository<Dog>
    {
        private readonly List<Dog> _store = new List<Dog> { new Dog { Name = "Buddy" } };
        public Dog GetById(int id) => _store[id];
        public IEnumerable<Dog> GetAll() => _store;
    }
}
